26	static void
27	compare_token(const struct lex_token *a, const struct lex_token *b)
28	{
29	    if (a->type != b->type) {
30	        fprintf(stderr, "type differs: %d -> %d\n", a->type, b->type);
31	        return;
32	    }
33	
34	    if (!((a->s && b->s && !strcmp(a->s, b->s))
35	          || (!a->s && !b->s))) {
36	        fprintf(stderr, "string differs: %s -> %s\n",
37	                a->s ? a->s : "(null)",
38	                b->s ? b->s : "(null)");
39	        return;
40	    }
41	
42	    if (a->type == LEX_T_INTEGER || a->type == LEX_T_MASKED_INTEGER) {
43	        if (memcmp(&a->value, &b->value, sizeof a->value)) {
44	            fprintf(stderr, "value differs\n");
45	            return;
46	        }
47	
48	        if (a->type == LEX_T_MASKED_INTEGER
49	            && memcmp(&a->mask, &b->mask, sizeof a->mask)) {
50	            fprintf(stderr, "mask differs\n");
51	            return;
52	        }
53	
54	        if (a->format != b->format
55	            && !(a->format == LEX_F_HEXADECIMAL
56	                 && b->format == LEX_F_DECIMAL
57	                 && a->value.integer == 0)) {
58	            fprintf(stderr, "format differs: %d -> %d\n",
59	                    a->format, b->format);
60	        }
61	    }
62	}
