65	test_lex(const char *input)
66	{
67	    struct ds output;
68	
69	    ds_init(&output);
70	    struct lexer lexer;
71	
72	    lexer_init(&lexer, input);
73	    ds_clear(&output);
74	    while (lexer_get(&lexer) != LEX_T_END) {
75	        size_t len = output.length;
76	        lex_token_format(&lexer.token, &output);
77	
78	        /* Check that the formatted version can really be parsed back
79	         * losslessly. */
80	        if (lexer.token.type != LEX_T_ERROR) {
81	            const char *s = ds_cstr(&output) + len;
82	            struct lexer l2;
83	
84	            lexer_init(&l2, s);
85	            lexer_get(&l2);
86	            compare_token(&lexer.token, &l2.token);
87	            lexer_destroy(&l2);
88	        }
89	        ds_put_char(&output, ' ');
90	    }
91	    lexer_destroy(&lexer);
92	
93	    ds_chomp(&output, ' ');
94	    puts(ds_cstr(&output));
95	    ds_destroy(&output);
96	}
