434	int
435	LLVMFuzzerTestOneInput(const uint8_t *input_, size_t size)
436	{
437	    /* Bail out if we cannot construct at least a 1 char string. */
438	    const char *input = (const char *) input_;
439	    if (size < 2 || input[size - 1] != '\0' || strchr(input, '\n')) {
440	        return 0;
441	    }
442	
443	    /* Disable logging to avoid write to disk. */
444	    static bool isInit = false;
445	    if (!isInit) {
446	        vlog_set_verbosity("off");
447	        isInit = true;
448	    }
449	
450	    /* Parse, annotate, simplify, normalize expr and convert to flows. */
451	    test_parse_expr(input);
452	
453	    /* Parse actions. */
454	    test_parse_actions(input);
455	
456	    /* Test OVN lexer. */
457	    test_lex(input);
458	
459	    /* Expr to packets. */
460	    test_expr_to_packets(input);
461	
462	    return 0;
463	}
